const numberButtons = document.querySelectorAll('.key-number');
const operatorButtons = document.querySelectorAll('.key-operator');
const equalsButton = document.querySelector('[data-action="equals"]');
const clearButton = document.querySelector('[data-action="clear"]');

let firstOperand = null;
let currentOperator = null;
let waitingForSecondOperand = false;
let hasError = false;

function updateDisplay(value) {
  display.textContent = value;
}

function resetState() {
  firstOperand = null;
  currentOperator = null;
  waitingForSecondOperand = false;
  hasError = false;
  display.classList.remove('error');
}

function inputNumber(value) {
  if (hasError) {
    resetState();
  }

  if (waitingForSecondOperand) {
    updateDisplay(value === '.' ? '0.' : value);
    waitingForSecondOperand = false;
    return;
  }

  const currentValue = display.textContent;

  if (value === '.') {
    if (!currentValue.includes('.')) {
      updateDisplay(`${currentValue}.`);
    }
    return;
  }

  updateDisplay(currentValue === '0' ? value : currentValue + value);
}

function formatResult(value) {
  const roundedResult = Number(value.toPrecision(12));
  return String(roundedResult);
}

function calculate(firstValue, secondValue, operator) {
  switch (operator) {
    case 'add':
      return firstValue + secondValue;
    case 'subtract':
      return firstValue - secondValue;
    case 'multiply':
      return firstValue * secondValue;
    case 'divide':
      if (secondValue === 0) {
        return null;
      }
      return firstValue / secondValue;
    default:
      return null;
  }
}

function showError(message) {
  resetState();
  hasError = true;
  display.classList.add('error');
  updateDisplay(message);
}

function handleOperator(nextOperator) {
  if (hasError) {
    return;
  }

  const inputValue = Number(display.textContent);

  if (currentOperator && waitingForSecondOperand) {
    currentOperator = nextOperator;
    return;
  }

  if (firstOperand === null) {
    firstOperand = inputValue;
  } else if (currentOperator) {
    const result = calculate(firstOperand, inputValue, currentOperator);

    if (result === null) {
      showError('除数不能为 0');
      return;
    }

    firstOperand = result;
    updateDisplay(formatResult(result));
  }

  currentOperator = nextOperator;
  waitingForSecondOperand = true;
}

function handleEquals() {
  if (hasError || currentOperator === null || firstOperand === null) {
    return;
  }

  const secondOperand = Number(display.textContent);
  const result = calculate(firstOperand, secondOperand, currentOperator);

  if (result === null) {
    showError('除数不能为 0');
    return;
  }

  updateDisplay(formatResult(result));
  firstOperand = null;
  currentOperator = null;
  waitingForSecondOperand = false;
}

function clearCalculator() {
  resetState();
  updateDisplay('0');
}

numberButtons.forEach((button) => {
  button.addEventListener('click', () => inputNumber(button.dataset.value));
});

operatorButtons.forEach((button) => {
  button.addEventListener('click', () => handleOperator(button.dataset.operator));
});

equalsButton.addEventListener('click', handleEquals);
clearButton.addEventListener('click', clearCalculator);
